package cn.binbin.crm;

import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class NotificationService {
    private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final DeliveryGuard guard;private final SalesService sales;private final AuthService auth;private final AttachmentService files;private final boolean enabled;
    public NotificationService(NamedParameterJdbcTemplate db,TransactionTemplate tx,DeliveryGuard guard,SalesService sales,AuthService auth,AttachmentService files,@Value("${CRM_REMINDER_SCHEDULE_ENABLED:false}") boolean enabled){this.db=db;this.tx=tx;this.guard=guard;this.sales=sales;this.auth=auth;this.files=files;this.enabled=enabled;}
    private static Map<String,Object> map(Object... args){return SaasService.parameters(args);}
    private AuthService.Actor actor(UUID tenant,UUID member){var t=db.queryForMap("SELECT * FROM sys_tenant WHERE id=:tenant",map("tenant",tenant));var m=db.queryForMap("SELECT display_name,department_id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:member",map("tenant",tenant,"member",member));var policies=db.queryForList("SELECT p.* FROM sys_role_policy p JOIN sys_member_role r ON r.tenant_id=p.tenant_id AND r.role_code=p.role_code WHERE r.tenant_id=:tenant AND r.member_id=:member",map("tenant",tenant,"member",member));var customer=CustomerAccess.from(policies);var value=new AuthService.Tenant(tenant,(String)t.get("code"),(String)t.get("name"),(String)t.get("status"),((java.sql.Timestamp)t.get("subscription_end")).toInstant(),member,(String)m.get("display_name"),Set.of());return new AuthService.Actor(null,value,customer,(UUID)m.get("department_id"),null,BusinessAccess.from(policies,customer),DeliveryAccess.from(policies));}
    private Map<String,Object> visible(AuthService.Actor a,Map<String,Object> n){if(!a.businessAccess().tasks().read())return null;try{var task=sales.task(a,(UUID)n.get("task_id"));LocalDate due=LocalDate.parse(String.valueOf(task.get("dueDate"))),today=LocalDate.now(ZoneId.of("Asia/Shanghai"));if(!a.tenant().memberId().equals(task.get("assigneeMemberId"))||!"PENDING".equals(task.get("status"))||due.isAfter(today)||((Number)task.get("version")).longValue()!=((Number)n.get("task_version")).longValue())return null;return map("id",n.get("id"),"taskId",n.get("task_id"),"title",task.get("title"),"kind",n.get("kind"),"dueDate",due,"readAt",n.get("read_at"),"createdAt",n.get("created_at"));}catch(ApiError hidden){return null;}}
    public Map<String,Object> list(AuthService.Session s){return guard.scoped(s,"notification",false,a->{var rows=db.queryForList("SELECT * FROM sys_notification WHERE tenant_id=:tenant AND member_id=:member ORDER BY created_at DESC,id LIMIT 200",map("tenant",a.tenant().id(),"member",a.tenant().memberId()));var result=new ArrayList<Map<String,Object>>();for(var n:rows){var v=visible(a,n);if(v!=null)result.add(SaasService.view(v));}return map("items",result,"unread",result.stream().filter(n->n.get("readAt")==null).count(),"limit",200);});}
    public void read(AuthService.Session s,UUID id){guard.scoped(s,"notification",false,a->{var rows=db.queryForList("SELECT * FROM sys_notification WHERE tenant_id=:tenant AND member_id=:member AND id=:id",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"id",id));if(rows.isEmpty()||visible(a,rows.getFirst())==null)throw ApiError.missing();db.update("UPDATE sys_notification SET read_at=coalesce(read_at,now()) WHERE tenant_id=:tenant AND member_id=:member AND id=:id",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"id",id));return null;});}
    private int reminders(UUID tenant){return tx.execute(status->{db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",map("tenant",tenant.toString()),String.class);LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));var tasks=db.queryForList("SELECT x.id,x.assignee_member_id,x.version,x.due_date FROM crm_task x JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.assignee_member_id JOIN iam_user u ON u.id=m.user_id WHERE x.tenant_id=:tenant AND x.status='PENDING' AND x.due_date<=:today AND m.status='ACTIVE' AND u.status='ACTIVE' ORDER BY x.due_date,x.id LIMIT 5000",map("tenant",tenant,"today",today));int count=0;for(var t:tasks){var a=actor(tenant,(UUID)t.get("assignee_member_id"));if(!a.businessAccess().tasks().read())continue;try{sales.task(a,(UUID)t.get("id"));}catch(ApiError denied){continue;}count+=db.update("INSERT INTO sys_notification(id,tenant_id,member_id,task_id,task_version,reminder_date,kind) VALUES(:id,:tenant,:member,:task,:version,:today,:kind) ON CONFLICT DO NOTHING",map("id",UUID.randomUUID(),"tenant",tenant,"member",t.get("assignee_member_id"),"task",t.get("id"),"version",t.get("version"),"today",today,"kind",LocalDate.parse(t.get("due_date").toString()).isBefore(today)?"OVERDUE":"DUE"));}return count;});}
    public Map<String,Object> run(AuthService.Session s,UUID tenant){auth.platform(s);return runJobs(tenant);}
    private Map<String,Object> runJobs(UUID selected){UUID job=UUID.randomUUID();db.update("INSERT INTO sys_job_run(id,job_name,status) VALUES(:id,'REMINDERS','RUNNING')",map("id",job));int processed=0,failed=0;var tenants=db.queryForList("SELECT id,status,subscription_end FROM sys_tenant WHERE cast(:selected AS uuid) IS NULL OR id=:selected ORDER BY id",map("selected",selected));for(var t:tenants){UUID id=(UUID)t.get("id");try{if("ACTIVE".equals(t.get("status"))&&((java.sql.Timestamp)t.get("subscription_end")).toInstant().isAfter(Instant.now()))processed+=reminders(id);var cleanup=files.cleanup(id);processed+=cleanup.processed();if(cleanup.failed()>0)failed++;}catch(Exception e){failed++;}}
        db.update("UPDATE sys_job_run SET status=:status,finished_at=now(),processed_count=:count,error_code=:error WHERE id=:id",map("id",job,"status",failed==0?"SUCCESS":"FAILED","count",processed,"error",failed==0?null:"TENANT_JOB_FAILED"));return map("id",job,"status",failed==0?"SUCCESS":"FAILED","processedCount",processed,"failedTenants",failed);
    }
    @Scheduled(initialDelay=30000,fixedDelay=300000) public void scheduled(){if(enabled)try{runJobs(null);}catch(Exception ignored){}}
    public boolean enabled(){return enabled;}
}
